CREATE EXTENSION IF NOT EXISTS postgis;

-- departments
CREATE TABLE departments (
    key VARCHAR(50) NOT NULL, 
    name VARCHAR(255) NOT NULL, 
    facility_type VARCHAR(30), 
    dial_timeout_seconds INTEGER NOT NULL, 
    repeat_cycles INTEGER NOT NULL, 
    alert_webhook_url TEXT, 
    timezone VARCHAR(50) NOT NULL, 
    id UUID NOT NULL, 
    is_active BOOLEAN DEFAULT '1' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    CONSTRAINT ck_departments_dial_timeout CHECK (dial_timeout_seconds BETWEEN 5 AND 120), 
    CONSTRAINT ck_departments_repeat_cycles CHECK (repeat_cycles BETWEEN 1 AND 5), 
    UNIQUE (key)
);


-- facilities
CREATE TABLE facilities (
