    PRIMARY KEY (id), 
    CONSTRAINT ck_facilities_type CHECK (type IN ('hospital', 'fire_station', 'police_station', 'shelter', 'government_office', 'other')), 
    CONSTRAINT ck_facilities_source CHECK (source IN ('seed', 'overpass', 'google_places')), 
    CONSTRAINT uq_facilities_source_place UNIQUE (source, external_place_id)
);

CREATE INDEX ix_facilities_department_key ON facilities (department_key);
